// 이 노드는 '지난 주 월요일 0시 ~ 이번 주 월요일 0시' 구간을 계산합니다.
// 아래에서 Supabase에 "이 기간에 들어온 문의만 주세요" 라고 조건을 걸 때 씁니다.
const now = new Date();

// 오늘이 무슨 요일인지 (0=일, 1=월 ...)
const day = now.getUTCDay();
// 이번 주 월요일 0시(UTC) 구하기
const daysSinceMonday = (day + 6) % 7;
const thisMonday = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - daysSinceMonday, 0, 0, 0));
// 지난 주 월요일 0시 = 이번 주 월요일 - 7일
const lastMonday = new Date(thisMonday.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    기간시작: lastMonday.toISOString(),   // 예: 2026-06-08T00:00:00.000Z
    기간끝: thisMonday.toISOString(),      // 예: 2026-06-15T00:00:00.000Z
    기간라벨: `${lastMonday.toISOString().slice(0, 10)} ~ ${thisMonday.toISOString().slice(0, 10)}`
  }
}];

// 조회된 문의들이 data 라는 배열 하나로 모여서 들어옵니다.
const rows = $json.data || [];

// 위에서 계산한 '기간 계산' 노드의 값을 그대로 가져와 제목에 씁니다.
const 기간라벨 = $('지난 주 기간 계산 (Code)').first().json.기간라벨;

const 총건수 = rows.length;

// 위험한 글자(<, >, &)를 메일에서 안전하게 보이도록 바꿔 줍니다.
function escapeHtml(text) {
  return String(text == null ? '' : text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function short(text, n) {
  const s = String(text == null ? '' : text);
  return s.length > n ? s.slice(0, n) + '…' : s;
}

// 문의 목록을 표(<tr>)로 한 줄씩 만듭니다.
let 표내용 = '';
if (총건수 === 0) {
  표내용 = '<tr><td colspan="3" style="padding:12px; text-align:center; color:#888;">지난 주에는 신규 문의가 없었습니다.</td></tr>';
} else {
  표내용 = rows.map((r) => {
    const 날짜 = String(r.created_at || '').slice(0, 10);
    return `<tr>
      <td style="padding:8px 10px; border-bottom:1px solid #eee;">${escapeHtml(날짜)}</td>
      <td style="padding:8px 10px; border-bottom:1px solid #eee;">${escapeHtml(r.name)}</td>
      <td style="padding:8px 10px; border-bottom:1px solid #eee;">${escapeHtml(short(r.message, 60))}</td>
    </tr>`;
  }).join('\n');
}

const 제목 = `[주간 리포트] 신규 문의 ${총건수}건 (${기간라벨})`;

const html = `<div style="font-family: sans-serif; max-width: 640px; margin: 0 auto; color:#222;">
  <h1 style="color:#2563eb; font-size:20px;">주간 신규 문의 요약 리포트</h1>
  <p style="color:#555;">대상 기간: <strong>${escapeHtml(기간라벨)}</strong></p>
  <p style="font-size:16px;">지난 주 신규 문의는 총 <strong style="color:#2563eb;">${총건수}건</strong> 입니다.</p>
  <table style="width:100%; border-collapse:collapse; font-size:14px; margin-top:12px;">
    <thead>
      <tr style="background:#f3f4f6; text-align:left;">
        <th style="padding:8px 10px; border-bottom:2px solid #ddd;">날짜</th>
        <th style="padding:8px 10px; border-bottom:2px solid #ddd;">이름</th>
        <th style="padding:8px 10px; border-bottom:2px solid #ddd;">문의 내용(요약)</th>
      </tr>
    </thead>
    <tbody>
      ${표내용}
    </tbody>
  </table>
  <hr style="border:none; border-top:1px solid #eee; margin:24px 0;">
  <p style="color:#888; font-size:12px;">이 메일은 매주 월요일 오전 9시에 자동 발송됩니다.</p>
</div>`;

return [{
  json: {
    총건수,
    기간라벨,
    제목,
    html
  }
}];
